function oa_assert($condition,$message): void { if(!$condition) throw new RuntimeException($message); }
function oa_case($name,$callback): void { global $results; try{$callback();$results[]=['name'=>$name,'pass'=>true];}catch(Throwable $e){$results[]=['name'=>$name,'pass'=>false,'error'=>$e->getMessage()];} }
function oa_t($name): string {return FG_Core::table($name);}
function oa_req($path,$params=[]): WP_REST_Request {$r=new WP_REST_Request('POST','/jalin-mcp/v1/'.$path); if($path==='oauth/register'){$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($params));}else{$r->set_header('Content-Type','application/x-www-form-urlencoded');$r->set_body_params($params);$r->set_body(http_build_query($params));}return $r;}
function oa_client($name): array {$r=FG_OAuth::register_client(oa_req('oauth/register',['client_name'=>$name,'redirect_uris'=>['https://claude.ai/api/mcp/auth_callback'],'token_endpoint_auth_method'=>'none']));oa_assert($r->get_status()===201,'Registration failed');return $r->get_data();}
function oa_grant($client,$override=[]): array {global $wpdb,$admin;$row=array_replace(['id'=>wp_generate_uuid4(),'client_id'=>$client['client_id'],'user_id'=>$admin->ID,'user_hash'=>hash_hmac('sha256',$admin->ID.'|'.$admin->user_pass.'|'.get_option('fg_oauth_epoch'),wp_salt('auth')),'resource'=>FG_OAuth::resource(),'allow_writes'=>1,'allow_sensitive'=>1,'status'=>'active','created'=>time(),'expires'=>time()+DAY_IN_SECONDS,'last_used'=>0],$override);oa_assert($wpdb->insert(oa_t('oauth_grants'),$row)===1,'Grant insert failed');return $row;}
function oa_list($id): array {$rows=FG_OAuth::connections();oa_assert(!is_wp_error($rows),'List failed');foreach($rows as $row)if($row['id']===$id)return $row;throw new RuntimeException('Connection missing');}
function oa_token($g): string {global $wpdb;$raw=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');oa_assert($wpdb->insert(oa_t('oauth_tokens'),['hash'=>hash('sha256',$raw),'grant_id'=>$g['id'],'kind'=>'access','status'=>'active','created'=>time(),'expires'=>time()+3600])===1,'Token insert failed');return $raw;}
