oa_case('read propose apply failure audit preserve client while admin review is explicit',function()use($token,$legacy,$wpdb){$r=oa_permission($token);foreach(['read','propose','apply','failure'] as $outcome)oa_assert(FG_Core::audit('client_fixture',$outcome),'Audit failed');FG_Core::audit('admin_fixture','approve','',['auth_source'=>'wordpress_admin']);$rows=$wpdb->get_results('SELECT * FROM '.oa_t('audit')." WHERE tool='client_fixture'",ARRAY_A);oa_assert(count($rows)===4,'Outcomes missing');foreach($rows as $row)oa_assert($row['client_name']==='Claude'&&$row['oauth_client_id']===$legacy['client_id'],'Wrong snapshot');$ar=$wpdb->get_row('SELECT * FROM '.oa_t('audit')." WHERE tool='admin_fixture'",ARRAY_A);oa_assert($ar['auth_source']==='wordpress_admin'&&$ar['oauth_client_id']===''&&$ar['client_name']==='WordPress Admin','Admin attributed to client');apply_filters('rest_request_after_callbacks',new WP_REST_Response([]),[],$r);oa_assert(FG_Auth::audit_context()['auth_source']==='','Context survived request');});
