final class OA_DB_Proxy {private $db;private $fault;public function __construct($db,$fault){$this->db=$db;$this->fault=$fault;}public function __get($k){return $this->db->$k;}public function __set($k,$v){$this->db->$k=$v;}public function __call($m,$a){$r=$this->db->$m(...$a);return ($this->fault)($m,$a,$r);}}
